// Exile Companion main window, part 1 of 10: storage, Path of Building decoding and parsing, build analysis, static game data, example build, state.
// Classic scripts loaded in order by index.html; they share one global scope, so order matters.
"use strict";
/* ---------------- storage ---------------- */
const store={
  get(k,d){try{const v=localStorage.getItem("ec330."+k);return v==null?d:JSON.parse(v)}catch(e){return d}},
  set(k,v){try{localStorage.setItem("ec330."+k,JSON.stringify(v))}catch(e){}}
};
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const $=id=>document.getElementById(id);
const fmt=n=>{n=Number(n)||0;if(Math.abs(n)>=1e6)return (n/1e6).toFixed(n>=1e7?1:2)+"M";if(Math.abs(n)>=1e4)return (n/1e3).toFixed(1)+"k";return Math.round(n).toLocaleString()};

/* ---------------- PoB decoding ---------------- */
async function inflate(bytes,format){
  const ds=new DecompressionStream(format);
  const stream=new Blob([bytes]).stream().pipeThrough(ds);
  return await new Response(stream).text();
}
async function decodePob(input){
  let code=(input||"").trim();
  if(!code) throw new Error("Paste a build code or choose a file first.");
  if(code.startsWith("<")) return code;
  if(/^https?:\/\//i.test(code)) throw new Error("That's a link. Open it, use the site's copy-code button, and paste the code here.");
  if(typeof DecompressionStream==="undefined") throw new Error("This browser can't unpack build codes. Update your browser, or export the build as XML from Path of Building and upload that.");
  let b64=code.replace(/\s+/g,"").replace(/-/g,"+").replace(/_/g,"/");
  while(b64.length%4) b64+="=";
  let bin;
  try{bin=atob(b64)}catch(e){throw new Error("The code has characters a PoB code never contains. Copy it again in full.")}
  const bytes=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
  for(const f of ["deflate","deflate-raw"]){
    try{const xml=await inflate(bytes,f);if(xml.includes("<PathOfBuilding")) return xml}catch(e){}
  }
  throw new Error("Couldn't unpack that code. It may be cut off: copy it again from Path of Building.");
}

/* ---------------- PoB parsing ---------------- */
const META_KEYS=/^(Unique ID|Item Level|Quality|Sockets|LevelReq|Implicits|Prefix|Suffix|Crafted|Variant|Selected Variant|Selected Alt Variant|Has Alt Variant|Has Alt Variant Two|League|Requires|Radius|Limited to|Armour|Evasion|Energy Shield|Ward|Catalyst|CatalystQuality|Talisman Tier|Cluster Jewel Skill|Cluster Jewel Node Count|ArmourBasePercentile|EvasionBasePercentile|EnergyShieldBasePercentile|WardBasePercentile|Item Tier|Source|Upgrade|Quality \(.+\)|Range|Socketed Gems|Imbued|Note)\s*:/i;
function parseItem(raw,id){
  const lines=raw.split(/\r?\n/).map(l=>l.trim()).filter(Boolean);
  const it={id,rarity:"NORMAL",name:"",base:"",ilvl:null,implicits:[],mods:[],flags:[],raw};
  let i=0;
  if(/^Rarity:/i.test(lines[0]||"")){it.rarity=lines[0].split(":")[1].trim().toUpperCase();i=1}
  if(it.rarity==="RARE"||it.rarity==="UNIQUE"||it.rarity==="RELIC"){it.name=lines[i]||"";it.base=lines[i+1]||"";i+=2;if(it.rarity==="RELIC")it.rarity="UNIQUE"}
  else{it.name=lines[i]||"";it.base=it.name;i+=1}
  let selVariant=null,implCount=0;const body=[];
  for(;i<lines.length;i++){
    const l=lines[i];
    let m;
    if((m=l.match(/^Selected Variant:\s*(\d+)/i))){selVariant=m[1];continue}
    if((m=l.match(/^Item Level:\s*(\d+)/i))){it.ilvl=+m[1];continue}
    if((m=l.match(/^Implicits:\s*(\d+)/i))){implCount=+m[1];body.length=0;continue}
    if(META_KEYS.test(l)) continue;
    if(/^(Shaper|Elder|Crusader|Hunter|Redeemer|Warlord|Searing Exarch|Eater of Worlds|Synthesised|Fractured) Item$/i.test(l)){it.flags.push(l.replace(/ Item$/,""));continue}
    if(/^(Corrupted|Mirrored|Split|Unidentified|Twice Corrupted)$/i.test(l)){it.flags.push(l);continue}
    body.push(l);
  }
  const clean=[];
  for(const l of body){
    const vm=l.match(/\{variant:([\d,]+)\}/);
    if(vm&&selVariant&&!vm[1].split(",").includes(selVariant)) continue;
    const crafted=/\{crafted\}/.test(l), fractured=/\{fractured\}/.test(l);
    const text=l.replace(/\{[^}]*\}/g,"").trim();
    if(text) clean.push({text,crafted,fractured});
  }
  it.implicits=clean.slice(0,implCount);
  it.mods=clean.slice(implCount);
  if(it.mods.some(m=>m.fractured)&&!it.flags.includes("Fractured")) it.flags.push("Fractured");
  return it;
}
function parsePob(xml){
  const doc=new DOMParser().parseFromString(xml,"application/xml");
  if(doc.querySelector("parsererror")||!doc.querySelector("PathOfBuilding")) throw new Error("That doesn't look like a Path of Building export.");
  const B=doc.querySelector("Build");
  const build={
    level:+(B?.getAttribute("level")||1),
    className:B?.getAttribute("className")||"Unknown",
    ascend:B?.getAttribute("ascendClassName")||"",
    mainSocketGroup:+(B?.getAttribute("mainSocketGroup")||1),
    stats:{},minionStats:{},skillSets:[],itemSets:[],items:{},specs:[],notes:"",activeSkillSet:1,activeItemSet:1,activeSpec:1
  };
  if(build.ascend==="None") build.ascend="";
  B?.querySelectorAll(":scope > PlayerStat").forEach(s=>build.stats[s.getAttribute("stat")]=+s.getAttribute("value"));
  B?.querySelectorAll(":scope > MinionStat").forEach(s=>build.minionStats[s.getAttribute("stat")]=+s.getAttribute("value"));
  // skills
  const S=doc.querySelector("Skills");
  if(S){
    build.activeSkillSet=+(S.getAttribute("activeSkillSet")||1);
    const sets=S.querySelectorAll(":scope > SkillSet");
    const readSkills=parent=>[...parent.querySelectorAll(":scope > Skill")].map(sk=>({
      label:sk.getAttribute("label")||"",slot:sk.getAttribute("slot")||"",enabled:sk.getAttribute("enabled")!=="false",
      mainActive:+(sk.getAttribute("mainActiveSkill")||1),
      gems:[...sk.querySelectorAll(":scope > Gem")].map(g=>({name:g.getAttribute("nameSpec")||g.getAttribute("skillId")||"?",level:+(g.getAttribute("level")||1),quality:+(g.getAttribute("quality")||0),enabled:g.getAttribute("enabled")!=="false",support:/Support/i.test(g.getAttribute("skillId")||g.getAttribute("gemId")||"")}))
    }));
    if(sets.length) sets.forEach((ss,i)=>build.skillSets.push({id:+(ss.getAttribute("id")||i+1),title:ss.getAttribute("title")||"Skill set "+(i+1),skills:readSkills(ss)}));
    else build.skillSets.push({id:1,title:"Default",skills:readSkills(S)});
  }
  // items
  const I=doc.querySelector("Items");
  if(I){
    build.activeItemSet=+(I.getAttribute("activeItemSet")||1);
    I.querySelectorAll(":scope > Item").forEach(el=>{const id=el.getAttribute("id");build.items[id]=parseItem(el.textContent||"",id)});
    const sets=I.querySelectorAll(":scope > ItemSet");
    const readSlots=p=>[...p.querySelectorAll(":scope > Slot")].map(s=>({name:s.getAttribute("name"),itemId:s.getAttribute("itemId")})).filter(s=>s.itemId&&s.itemId!=="0");
    if(sets.length) sets.forEach((st,i)=>build.itemSets.push({id:+(st.getAttribute("id")||i+1),title:st.getAttribute("title")||"Item set "+(i+1),slots:readSlots(st)}));
    else build.itemSets.push({id:1,title:"Default",slots:readSlots(I)});
  }
  // tree
  const T=doc.querySelector("Tree");
  if(T){
    build.activeSpec=+(T.getAttribute("activeSpec")||1);
    T.querySelectorAll(":scope > Spec").forEach((sp,i)=>{
      const nodes=(sp.getAttribute("nodes")||"").split(",").filter(Boolean);
      const url=(sp.querySelector("URL")?.textContent||"").trim();
      const sockets=[...sp.querySelectorAll("Sockets > Socket")].map(s=>({node:s.getAttribute("nodeId"),itemId:s.getAttribute("itemId")})).filter(x=>x.itemId&&x.itemId!=="0");
      const jewels=sockets.map(x=>x.itemId);
      build.specs.push({title:sp.getAttribute("title")||"Tree "+(i+1),version:sp.getAttribute("treeVersion")||"",nodes:nodes.length,ids:nodes,url,jewels,sockets});
    });
  }
  build.notes=(doc.querySelector("Notes")?.textContent||"").replace(/\^x?[0-9A-Fa-f]{1,6}/g,"").trim();
  return build;
}

/* ---------------- build analysis ---------------- */
const CURSES=/^(Vulnerability|Elemental Weakness|Flammability|Frostbite|Conductivity|Despair|Enfeeble|Temporal Chains|Punishment|Assassin's Mark|Poacher's Mark|Warlords?'s Mark|Sniper's Mark|Hextouch|Curse on Hit|Blasphemy)/i;
const MINION=/(Raise|Summon|Animate|Spectre|Golem|Skeleton|Zombie|Absolution|Dominating Blow|Herald of Purity|Herald of Agony|Carrion|Minion)/i;
const ELEM={
  fire:/(Fire|Flame|Burn|Ignit|Immolat|Infern|Magma|Molten|Volcan|Cremation|Incinerate|Righteous|Explosive|Pyro|Combust)/i,
  cold:/(Ice|Frost|Cold|Glacial|Freez|Vortex|Winter|Hypotherm|Arctic|Cold Snap|Eye of Winter|Tornado Shot)/i,
  lightning:/(Lightning|\bArc\b|Spark|Storm|Shock|Galvanic|Crackling|Static|Kinetic|Ball Lightning|Thunder|Voltaxic|Tempest)/i,
  chaos:/(Chaos|Poison|Toxic|Bane|Contagion|Essence Drain|Soulrend|Blight|Caustic|Wither|Void|Forbidden Rite|Dark Pact)/i,
  phys:/(Bleed|Brutality|Impale|Ruthless|Earthquake|Sunder|Cyclone|Lacerate|Blade|Boneshatter|Splitting Steel|Shrapnel|Exsanguinate|Reap|Puncture|Ground Slam|Perforate|Tectonic|Flicker|Cleave|Spectral Throw|Double Strike)/i
};
const DOT=/(Ignite|Poison|Bleed|Burn|Righteous Fire|Essence Drain|Bane|Caustic|Toxic Rain|Death Aura|Vortex|Cremation|Wither|Exsanguinate|Reap|Corrupting Fever|Scorching Ray|Fire Trap|Soulrend|Contagion|Decay|Deadly Ailments|Swift Affliction)/i;

function currentSkills(b){const s=b.skillSets.find(x=>x.id===b.activeSkillSet)||b.skillSets[0];return s?s.skills:[]}
function currentSlots(b){const s=b.itemSets.find(x=>x.id===b.activeItemSet)||b.itemSets[0];return s?s.slots:[]}
function currentSpec(b){return b.specs[(b.activeSpec||1)-1]||b.specs[0]||null}
function mainGroup(b){const sk=currentSkills(b);return sk[(b.mainSocketGroup||1)-1]||sk.find(s=>s.gems.length)||null}
function mainSkillName(b){const g=mainGroup(b);if(!g)return"Unknown skill";const act=g.gems.filter(x=>!x.support&&!/Support$/i.test(x.name));return (act[(g.mainActive||1)-1]||act[0]||g.gems[0]||{name:"Unknown skill"}).name}

function analyze(b){
  const st=b.stats, sk=currentSkills(b), mg=mainGroup(b);
  const all=sk.flatMap(s=>s.enabled?s.gems.filter(g=>g.enabled):[]);
  const mainNames=(mg?mg.gems.map(g=>g.name):[]).join(" ");
  const items=currentSlots(b).map(s=>b.items[s.itemId]).filter(Boolean);
  const modText=items.flatMap(i=>[...i.implicits,...i.mods].map(m=>m.text)).join("\n");
  const dps=Math.max(st.FullDPS||0,st.CombinedDPS||0,st.TotalDPS||0,st.TotalDotDPS||0,(b.minionStats&&(b.minionStats.TotalDPS||b.minionStats.CombinedDPS))||0);
  const life=st.Life||0, es=st.EnergyShield||0, ward=st.Ward||0;
  const pool=life+es+ward;
  const ehp=st.TotalEHP||pool;
  const res={fire:st.FireResist??null,cold:st.ColdResist??null,lightning:st.LightningResist??null,chaos:st.ChaosResist??null};
  const elems=Object.entries(ELEM).filter(([k,r])=>r.test(mainNames)).map(([k])=>k);
  const t={
    dps,life,es,ward,pool,ehp,res,
    main:mainSkillName(b),
    minion:MINION.test(mainSkillName(b))||MINION.test(mainNames),
    totem:/Totem|Ballista/i.test(mainNames), trap:/Trap|Mine/i.test(mainNames),
    dot:DOT.test(mainNames),
    elems:elems.length?elems:["phys"],
    curses:all.some(g=>CURSES.test(g.name))||/Curse Enemies|Hits/i.test(modText)&&/Curse/i.test(modText),
    leech:/Leech/i.test(modText)||all.some(g=>/Leech/i.test(g.name)),
    regen:(st.LifeRegenRecovery||st.LifeRegen||0)>Math.max(150,life*0.04)||/Regenerate .* Life per second/i.test(modText),
    charges:/Frenzy Charge|Power Charge|Endurance Charge/i.test(modText)||all.some(g=>/Charge|Blood Rage|Assassin's Mark|Poacher's Mark|Warlord's Mark/i.test(g.name)),
    flasks:/Flask/i.test(modText),
    esBased:es>life
  };
  t.boss=dps>=5e6?3:dps>=1e6?2:1;
  t.tank=ehp>=40000||pool>=7000?3:ehp>=15000||pool>=4500?2:1;
  return t;
}

