/* ---------------- state ---------------- */
let B=null, T=null, isExample=true, selectedItem=null, selectedSlot=null;
let G=null, TG=null, C=null, TC=null, exG=true, exC=true;
const S_DEFAULT=()=>({progress:{},strat:null,prof:null,budget:1,clear:2,avoidOff:{},want:"",session:{start:null,elapsed:0,maps:[]},divine:150,calc:{cost:20,sell:300,chance:15}});
const S=(()=>{let s=store.get("state",null);if(!s||typeof s!=="object"||Array.isArray(s))s={};
  // fill in anything missing (an older or partly damaged save) so a page never crashes on it
  const d=S_DEFAULT();for(const k in d){const v=s[k],dv=d[k];if(v===undefined||v===null&&dv!==null||(dv&&typeof dv==="object"&&(typeof v!=="object"||v===null||Array.isArray(v)!==Array.isArray(dv))))s[k]=dv}
  if(!Array.isArray(s.session.maps))s.session.maps=[];return s})();
const save=()=>store.set("state",S);

function reanalyze(){TG=G?analyze(G):null;TC=C?analyze(C):null}
async function loadSlot(slot,xml,example,noRender){
  const b=parsePob(xml);
  if(slot==="current"){C=b;exC=!!example;if(!example)store.set("xml.current",xml)}
  else{G=b;exG=!!example;if(!example)store.set("xml.goal",xml);selectedItem=null;selectedSlot=null}
  reanalyze();
  if(!noRender) renderAll();
  pobPushBuild();
}
// Path of Building numbers compare items against what you wear: your current character, else your goal build
function pobPushBuild(){try{if(typeof DESK==="undefined"||!DESK||!DESK.pobBuild)return;const x=(C&&!exC&&store.get("xml.current",null))||(G&&!exG&&store.get("xml.goal",null))||"";DESK.pobBuild(x)}catch(e){}}
function clearSlot(slot){if(slot==="current"){C=null;TC=null;try{localStorage.removeItem("ec330.xml.current")}catch(e){}}renderAll();pobPushBuild()}
function withBuild(b,fn){const pB=B,pT=T,pE=isExample;if(b){B=b;T=b===C?TC:TG;isExample=b===C?exC:exG}try{return fn()}finally{B=pB;T=pT;isExample=pE}}
const liveB=()=>C||G;
const viewB=()=>S.view==="current"&&C?C:G;
function slotItemsOf(b){return withBuild(b,()=>slotItems())}
